// 由 scripts/sync-runtime.mjs 自动生成（postinstall / sync:runtime），勿手改。
// 平台 proto-shared 各模块的源码文本，供原型 TSX 浏览器端编译（esbuild-wasm）时作为 bundle 输入。
export const PROTO_SHARED_SOURCES: Record<string, string> = {
  "index.ts": "/**\n * proto-shared：Agent 原型共享库统一导出\n * =====================================================\n * 平台内置共享库（web/src/components/docs/proto-shared/），供 agent 原型通过\n * `@proto/shared`（或相对 `../_shared/*`）import。编译链路把别名解析到本目录，\n * 与 md-docs 的 docs/agent-platform/prototypes/_shared 保持一致。\n *\n * 冲突处理：components.tsx（任务状态版 StatusBadge）与 ui.tsx（tone 版 StatusBadge）\n * 同名导出，ui 版在统一导出中重命名为 UiStatusBadge。\n */\nexport * from \"./styles\";\nexport * from \"./components\";\nexport * from \"./nav\";\nexport * from \"./types\";\n\nexport {\n  StatusBadge as UiStatusBadge,\n  ProgressBar,\n  Avatar,\n  Button,\n  IconSearch,\n  IconPlus,\n  IconEdit,\n  IconMore,\n  IconChevronLeft,\n  IconChevronRight,\n  IconLock,\n  IconClock,\n  IconMonitor,\n  IconSmartphone,\n  IconRefresh,\n} from \"./ui\";\n",
  "styles.ts": "/**\n * Agent Platform 原型设计 token\n * =============================================\n * 供 _shared/components.tsx 与各原型页面（T8~T11）统一引用。\n * 原则：所有颜色/间距/圆角/字号都收敛在此，组件内不散落 magic number。\n */\n\n/* ---------------------------------- 角色 ---------------------------------- */\nexport type RoleKey = \"product\" | \"architect\" | \"developer\" | \"tester\";\n\nexport interface RoleTheme {\n  label: string;\n  color: string;\n  bg: string;\n  border: string;\n}\n\n/** 四类 Agent 角色的语义色（产品=蓝 / 架构=紫 / 开发=绿 / 测试=橙） */\nexport const roles: Record<RoleKey, RoleTheme> = {\n  product: { label: \"产品经理\", color: \"#3B82F6\", bg: \"#EFF6FF\", border: \"#BFDBFE\" },\n  architect: { label: \"架构师\", color: \"#8B5CF6\", bg: \"#F5F3FF\", border: \"#DDD6FE\" },\n  developer: { label: \"开发者\", color: \"#10B981\", bg: \"#ECFDF5\", border: \"#A7F3D0\" },\n  tester: { label: \"测试\", color: \"#F59E0B\", bg: \"#FFFBEB\", border: \"#FDE68A\" },\n};\n\n/** 角色对应导航/面板上的强调色（深一档，用于文字） */\nexport const roleText: Record<RoleKey, string> = {\n  product: \"#2563EB\",\n  architect: \"#7C3AED\",\n  developer: \"#059669\",\n  tester: \"#D97706\",\n};\n\n/* ---------------------------------- 任务状态 ---------------------------------- */\nexport type StatusKey = \"进行中\" | \"待验收\" | \"已完成\" | \"已归档\";\n\nexport interface StatusTheme {\n  color: string;\n  bg: string;\n  border: string;\n}\n\n/** 任务状态四色：进行中=蓝 / 待验收=琥珀 / 已完成=绿 / 已归档=灰 */\nexport const statusColors: Record<StatusKey, StatusTheme> = {\n  \"进行中\": { color: \"#2563EB\", bg: \"#EFF6FF\", border: \"#BFDBFE\" },\n  \"待验收\": { color: \"#D97706\", bg: \"#FFFBEB\", border: \"#FDE68A\" },\n  \"已完成\": { color: \"#059669\", bg: \"#ECFDF5\", border: \"#A7F3D0\" },\n  \"已归档\": { color: \"#64748B\", bg: \"#F1F5F9\", border: \"#E2E8F0\" },\n};\n\n/* ---------------------------------- 中性色 ---------------------------------- */\nexport const neutral = {\n  900: \"#0F172A\",\n  800: \"#1E293B\",\n  700: \"#334155\",\n  600: \"#475569\",\n  500: \"#64748B\",\n  400: \"#94A3B8\",\n  300: \"#CBD5E1\",\n  200: \"#E2E8F0\",\n  100: \"#F1F5F9\",\n  50: \"#F8FAFC\",\n} as const;\n\n/* ---------------------------------- 间距（4px 基准） ---------------------------------- */\nexport const space = { xs: 4, sm: 8, md: 12, lg: 16, xl: 24, xxl: 32 } as const;\n\n/* ---------------------------------- 圆角 ---------------------------------- */\nexport const radius = { sm: 6, md: 10, lg: 14, pill: 999 } as const;\n\n/* ---------------------------------- 字号 ---------------------------------- */\nexport const fontSize = {\n  xs: 11,\n  sm: 12,\n  md: 13,\n  lg: 15,\n  xl: 18,\n  xxl: 22,\n} as const;\n\n/* ---------------------------------- 字体 ---------------------------------- */\nexport const fontFamily = {\n  body: `\"PingFang SC\", \"HarmonyOS Sans SC\", \"Microsoft YaHei\", -apple-system, \"Segoe UI\", sans-serif`,\n  display: `Sora, \"PingFang SC\", \"HarmonyOS Sans SC\", \"Microsoft YaHei\", sans-serif`,\n  mono: `\"JetBrains Mono\", \"SFMono-Regular\", Consolas, \"Liberation Mono\", monospace`,\n} as const;\n\n/* ---------------------------------- 阴影 ---------------------------------- */\nexport const shadow = {\n  sm: \"0 1px 2px rgba(15,23,42,.05), 0 1px 3px rgba(15,23,42,.08)\",\n  md: \"0 4px 14px rgba(15,23,42,.08), 0 2px 4px rgba(15,23,42,.05)\",\n  lg: \"0 16px 40px rgba(15,23,42,.14)\",\n} as const;\n\n/* ---------------------------------- 侧边栏（深色） ---------------------------------- */\nexport const sidebarTheme = {\n  bg: \"#0F172A\",\n  bgActive: \"rgba(255,255,255,.08)\",\n  text: \"#94A3B8\",\n  textActive: \"#F8FAFC\",\n  border: \"rgba(255,255,255,.06)\",\n} as const;\n",
  "components.tsx": "/**\n * Agent Platform 共享 UI 组件库\n * =============================================\n * 供 docs/agent-platform/prototypes 下各原型（T8~T11）统一使用。\n * - 纯展示组件，不承载任何交互逻辑（点击/跳转/状态变更）。\n * - 颜色 / 间距 / 圆角 / 字号一律取自 ./styles.ts token。\n * - 关键元素带 data-testid，供后续 playwright 断言。\n *\n * 引入方式（原型内相对 import）：\n *   import { AgentAvatar, ChatBubble, ... } from \"../../_shared/components\";\n */\nimport type { CSSProperties, ReactNode } from \"react\";\nimport {\n  type RoleKey,\n  type StatusKey,\n  roles,\n  roleText,\n  statusColors,\n  neutral,\n  space,\n  radius,\n  fontSize,\n  fontFamily,\n  shadow,\n  sidebarTheme,\n} from \"./styles\";\n\nconst baseFont: CSSProperties = { fontFamily: fontFamily.body };\n\n/* ================================ AgentAvatar ================================\n * Agent 头像：圆形头像 + 角色色块，右下角带角色小圆点。\n */\nexport interface AgentAvatarProps {\n  /** 角色 key，决定色块颜色 */\n  role: RoleKey;\n  /** 头像内展示的缩写（缺省取角色 key 首字母大写） */\n  initials?: string;\n  /** 尺寸：sm=28 / md=36 / lg=44 */\n  size?: \"sm\" | \"md\" | \"lg\";\n  /** 是否显示右下角色点 */\n  dot?: boolean;\n  style?: CSSProperties;\n  className?: string;\n}\n\nconst avatarSizes = { sm: 28, md: 36, lg: 44 } as const;\n\nexport function AgentAvatar({\n  role,\n  initials,\n  size = \"md\",\n  dot = true,\n  style,\n  className,\n}: AgentAvatarProps) {\n  const dim = avatarSizes[size];\n  const theme = roles[role];\n  const dotDim = Math.max(8, Math.round(dim * 0.28));\n  return (\n    <span\n      data-testid=\"agent-avatar\"\n      data-role={role}\n      aria-label={`${theme.label} 头像`}\n      className={className}\n      style={{\n        position: \"relative\",\n        display: \"inline-flex\",\n        alignItems: \"center\",\n        justifyContent: \"center\",\n        width: dim,\n        height: dim,\n        borderRadius: \"50%\",\n        backgroundColor: theme.bg,\n        border: `1.5px solid ${theme.border}`,\n        color: theme.color,\n        fontSize: Math.round(dim * 0.36),\n        fontWeight: 600,\n        lineHeight: 1,\n        userSelect: \"none\",\n        flexShrink: 0,\n        ...baseFont,\n        ...style,\n      }}\n    >\n      {(initials ?? role.charAt(0).toUpperCase())}\n      {dot && (\n        <span\n          aria-hidden\n          style={{\n            position: \"absolute\",\n            right: -1,\n            bottom: -1,\n            width: dotDim,\n            height: dotDim,\n            borderRadius: \"50%\",\n            backgroundColor: theme.color,\n            border: `2px solid #FFFFFF`,\n          }}\n        />\n      )}\n    </span>\n  );\n}\n\n/* ================================ AgentBadge ================================\n * 角色标签：产品经理 / 架构师 / 开发者 / 测试\n */\nexport interface AgentBadgeProps {\n  role: RoleKey;\n  /** 是否显示前置小圆点 */\n  dot?: boolean;\n  style?: CSSProperties;\n  className?: string;\n}\n\nexport function AgentBadge({ role, dot = true, style, className }: AgentBadgeProps) {\n  const theme = roles[role];\n  return (\n    <span\n      data-testid=\"agent-badge\"\n      data-role={role}\n      className={className}\n      style={{\n        display: \"inline-flex\",\n        alignItems: \"center\",\n        gap: space.xs,\n        padding: `${space.xs - 1}px ${space.sm}px`,\n        borderRadius: radius.pill,\n        backgroundColor: theme.bg,\n        border: `1px solid ${theme.border}`,\n        color: roleText[role],\n        fontSize: fontSize.sm,\n        fontWeight: 500,\n        lineHeight: 1.4,\n        whiteSpace: \"nowrap\",\n        ...baseFont,\n        ...style,\n      }}\n    >\n      {dot && (\n        <span\n          aria-hidden\n          style={{\n            width: 6,\n            height: 6,\n            borderRadius: \"50%\",\n            backgroundColor: theme.color,\n            flexShrink: 0,\n          }}\n        />\n      )}\n      {theme.label}\n    </span>\n  );\n}\n\n/* ================================ ChatBubble ================================\n * 消息气泡：user=右对齐蓝 / agent=左对齐白卡带角色 / system=居中灰\n */\nexport type ChatMessageType = \"user\" | \"agent\" | \"system\";\n\nexport interface ChatBubbleProps {\n  text: string;\n  type?: ChatMessageType;\n  /** 发送人（agent / system 消息展示） */\n  author?: string;\n  /** 发送人角色（agent 消息展示角色色） */\n  role?: RoleKey;\n  /** 可选时间戳 */\n  time?: string;\n  style?: CSSProperties;\n  className?: string;\n}\n\nexport function ChatBubble({\n  text,\n  type = \"agent\",\n  author,\n  role,\n  time,\n  style,\n  className,\n}: ChatBubbleProps) {\n  const isUser = type === \"user\";\n  const isSystem = type === \"system\";\n  const roleTheme = role ? roles[role] : null;\n\n  // 气泡外壳\n  const bubbleBase: CSSProperties = {\n    maxWidth: \"78%\",\n    padding: `${space.md}px ${space.lg}px`,\n    borderRadius: radius.lg,\n    fontSize: fontSize.md,\n    lineHeight: 1.6,\n    whiteSpace: \"pre-wrap\",\n    wordBreak: \"break-word\",\n    ...baseFont,\n  };\n\n  if (isSystem) {\n    return (\n      <div\n        data-testid=\"chat-bubble\"\n        data-type=\"system\"\n        className={className}\n        style={{ display: \"flex\", justifyContent: \"center\", ...style }}\n      >\n        <div\n          style={{\n            ...bubbleBase,\n            backgroundColor: neutral[100],\n            color: neutral[500],\n            fontSize: fontSize.sm,\n            padding: `${space.sm}px ${space.md}px`,\n            borderRadius: radius.pill,\n          }}\n        >\n          {text}\n        </div>\n      </div>\n    );\n  }\n\n  const showHeader = !isUser && (author || roleTheme);\n  return (\n    <div\n      data-testid=\"chat-bubble\"\n      data-type={type}\n      className={className}\n      style={{\n        display: \"flex\",\n        flexDirection: isUser ? \"row-reverse\" : \"row\",\n        alignItems: \"flex-start\",\n        gap: space.sm,\n        ...style,\n      }}\n    >\n      {!isUser && (\n        <AgentAvatar role={role ?? \"developer\"} size=\"sm\" dot={false} style={{ marginTop: 2 }} />\n      )}\n      <div\n        style={{\n          display: \"flex\",\n          flexDirection: \"column\",\n          alignItems: isUser ? \"flex-end\" : \"flex-start\",\n          gap: space.xs,\n        }}\n      >\n        {showHeader && (\n          <span\n            data-testid=\"chat-bubble-author\"\n            style={{\n              fontSize: fontSize.xs,\n              color: roleTheme ? roleText[role!] : neutral[400],\n              fontWeight: 500,\n              ...baseFont,\n            }}\n          >\n            {author ?? roleTheme!.label}\n            {time ? ` · ${time}` : \"\"}\n          </span>\n        )}\n        <div\n          style={\n            isUser\n              ? {\n                  ...bubbleBase,\n                  backgroundColor: \"#2563EB\",\n                  color: \"#FFFFFF\",\n                  borderTopRightRadius: radius.sm,\n                  boxShadow: shadow.sm,\n                }\n              : {\n                  ...bubbleBase,\n                  backgroundColor: \"#FFFFFF\",\n                  color: neutral[800],\n                  border: `1px solid ${neutral[200]}`,\n                  borderTopLeftRadius: radius.sm,\n                  boxShadow: shadow.sm,\n                }\n          }\n        >\n          {text}\n        </div>\n      </div>\n    </div>\n  );\n}\n\n/* ================================ MessageInput ================================\n * 输入区：@ 提示区域样式 + 输入占位 + 发送按钮（纯展示）\n */\nexport interface MessageInputProps {\n  /** 可 @ 的 Agent 角色列表（渲染为提示 chips） */\n  mentionable?: RoleKey[];\n  placeholder?: string;\n  style?: CSSProperties;\n  className?: string;\n}\n\nexport function MessageInput({\n  mentionable = [\"product\", \"architect\", \"developer\", \"tester\"],\n  placeholder = \"输入消息，@ 提及某个 Agent…\",\n  style,\n  className,\n}: MessageInputProps) {\n  return (\n    <div\n      data-testid=\"message-input\"\n      className={className}\n      style={{\n        border: `1px solid ${neutral[200]}`,\n        borderRadius: radius.lg,\n        backgroundColor: \"#FFFFFF\",\n        padding: space.md,\n        boxShadow: shadow.sm,\n        display: \"flex\",\n        flexDirection: \"column\",\n        gap: space.sm,\n        ...baseFont,\n        ...style,\n      }}\n    >\n      {/* @ 提示区域 */}\n      <div\n        data-testid=\"message-input-mentions\"\n        style={{\n          display: \"flex\",\n          alignItems: \"center\",\n          gap: space.sm,\n          flexWrap: \"wrap\",\n          paddingBottom: space.sm,\n          borderBottom: `1px dashed ${neutral[200]}`,\n        }}\n      >\n        <span style={{ fontSize: fontSize.sm, color: neutral[400], fontWeight: 500 }}>\n          @提及：\n        </span>\n        {mentionable.map((role) => (\n          <AgentBadge key={role} role={role} />\n        ))}\n      </div>\n      {/* 输入占位 */}\n      <div\n        aria-hidden\n        style={{\n          minHeight: 40,\n          color: neutral[400],\n          fontSize: fontSize.md,\n          lineHeight: 1.6,\n          padding: `${space.xs}px ${space.sm}px`,\n        }}\n      >\n        {placeholder}\n      </div>\n      {/* 操作行：发送按钮 */}\n      <div style={{ display: \"flex\", justifyContent: \"flex-end\" }}>\n        <span\n          data-testid=\"message-input-send\"\n          style={{\n            display: \"inline-flex\",\n            alignItems: \"center\",\n            gap: space.xs,\n            padding: `${space.sm}px ${space.lg}px`,\n            borderRadius: radius.pill,\n            backgroundColor: \"#2563EB\",\n            color: \"#FFFFFF\",\n            fontSize: fontSize.md,\n            fontWeight: 500,\n            cursor: \"pointer\",\n            ...baseFont,\n          }}\n        >\n          发送\n        </span>\n      </div>\n    </div>\n  );\n}\n\n/* ================================ StatusBadge ================================\n * 任务状态徽章：进行中 / 待验收 / 已完成 / 已归档\n */\nexport interface StatusBadgeProps {\n  status: StatusKey;\n  style?: CSSProperties;\n  className?: string;\n}\n\nexport function StatusBadge({ status, style, className }: StatusBadgeProps) {\n  const theme = statusColors[status];\n  return (\n    <span\n      data-testid=\"status-badge\"\n      data-status={status}\n      className={className}\n      style={{\n        display: \"inline-flex\",\n        alignItems: \"center\",\n        gap: space.xs,\n        padding: `${space.xs}px ${space.sm + 2}px`,\n        borderRadius: radius.pill,\n        backgroundColor: theme.bg,\n        border: `1px solid ${theme.border}`,\n        color: theme.color,\n        fontSize: fontSize.sm,\n        fontWeight: 500,\n        lineHeight: 1.4,\n        whiteSpace: \"nowrap\",\n        ...baseFont,\n        ...style,\n      }}\n    >\n      <span\n        aria-hidden\n        style={{\n          width: 7,\n          height: 7,\n          borderRadius: \"50%\",\n          backgroundColor: theme.color,\n          flexShrink: 0,\n        }}\n      />\n      {status}\n    </span>\n  );\n}\n\n/* ================================ Sidebar ================================\n * 左侧导航：项目名 + 导航项（任务 / Agent 管理）\n */\nexport type SidebarNavKey = \"tasks\" | \"agents\";\n\nexport interface SidebarProps {\n  projectName?: string;\n  active?: SidebarNavKey;\n  onNavClick?: (key: SidebarNavKey) => void;\n  style?: CSSProperties;\n  className?: string;\n}\n\nconst NAV_ITEMS: { key: SidebarNavKey; label: string; icon: string }[] = [\n  { key: \"tasks\", label: \"任务\", icon: \"▤\" },\n  { key: \"agents\", label: \"Agent 管理\", icon: \"◉\" },\n];\n\nexport function Sidebar({\n  projectName = \"Agent 协作平台\",\n  active = \"tasks\",\n  onNavClick,\n  style,\n  className,\n}: SidebarProps) {\n  return (\n    <aside\n      data-testid=\"sidebar\"\n      className={className}\n      style={{\n        width: 220,\n        flexShrink: 0,\n        height: \"100%\",\n        backgroundColor: sidebarTheme.bg,\n        color: sidebarTheme.text,\n        display: \"flex\",\n        flexDirection: \"column\",\n        ...baseFont,\n        ...style,\n      }}\n    >\n      {/* 项目名 */}\n      <div\n        data-testid=\"sidebar-project\"\n        style={{\n          padding: space.xl,\n          borderBottom: `1px solid ${sidebarTheme.border}`,\n        }}\n      >\n        <div\n          style={{\n            width: 34,\n            height: 34,\n            borderRadius: radius.md,\n            background: \"linear-gradient(135deg,#3B82F6,#8B5CF6)\",\n            display: \"flex\",\n            alignItems: \"center\",\n            justifyContent: \"center\",\n            color: \"#FFFFFF\",\n            fontWeight: 700,\n            fontSize: fontSize.lg,\n            marginBottom: space.md,\n          }}\n        >\n          A\n        </div>\n        <div\n          style={{\n            color: sidebarTheme.textActive,\n            fontSize: fontSize.md,\n            fontWeight: 600,\n            lineHeight: 1.4,\n          }}\n        >\n          {projectName}\n        </div>\n        <div style={{ fontSize: fontSize.xs, color: sidebarTheme.text, marginTop: 2 }}>\n          智能体协作工作区\n        </div>\n      </div>\n\n      {/* 导航项 */}\n      <nav style={{ padding: space.md, display: \"flex\", flexDirection: \"column\", gap: space.xs }}>\n        {NAV_ITEMS.map((item) => {\n          const isActive = item.key === active;\n          return (\n            <button\n              key={item.key}\n              type=\"button\"\n              data-testid={`sidebar-nav-${item.key}`}\n              data-active={isActive ? \"true\" : \"false\"}\n              onClick={onNavClick ? () => onNavClick(item.key) : undefined}\n              style={{\n                display: \"flex\",\n                alignItems: \"center\",\n                gap: space.sm + 2,\n                padding: `${space.sm + 2}px ${space.md}px`,\n                borderRadius: radius.md,\n                border: \"none\",\n                cursor: \"pointer\",\n                textAlign: \"left\",\n                backgroundColor: isActive ? sidebarTheme.bgActive : \"transparent\",\n                color: isActive ? sidebarTheme.textActive : sidebarTheme.text,\n                fontSize: fontSize.md,\n                fontWeight: isActive ? 600 : 400,\n                transition: \"background-color .15s ease\",\n                fontFamily: fontFamily.body,\n              }}\n            >\n              <span style={{ fontSize: fontSize.lg, lineHeight: 1, opacity: 0.9 }} aria-hidden>\n                {item.icon}\n              </span>\n              {item.label}\n            </button>\n          );\n        })}\n      </nav>\n\n      {/* 底部占位 */}\n      <div\n        style={{\n          marginTop: \"auto\",\n          padding: space.lg,\n          borderTop: `1px solid ${sidebarTheme.border}`,\n          fontSize: fontSize.xs,\n          color: sidebarTheme.text,\n          lineHeight: 1.5,\n        }}\n      >\n        4 个 Agent 在线\n      </div>\n    </aside>\n  );\n}\n\n/* ================================ TopBar ================================\n * 顶部栏：页面标题 + 用户信息占位\n */\nexport interface TopBarProps {\n  title?: string;\n  subtitle?: string;\n  userName?: string;\n  userRole?: string;\n  style?: CSSProperties;\n  className?: string;\n}\n\nexport function TopBar({\n  title = \"任务看板\",\n  subtitle,\n  userName = \"运营者\",\n  userRole = \"项目管理员\",\n  style,\n  className,\n}: TopBarProps) {\n  const initials = userName.slice(0, 1);\n  return (\n    <header\n      data-testid=\"topbar\"\n      className={className}\n      style={{\n        height: 60,\n        flexShrink: 0,\n        display: \"flex\",\n        alignItems: \"center\",\n        justifyContent: \"space-between\",\n        padding: `0 ${space.xl}px`,\n        backgroundColor: \"#FFFFFF\",\n        borderBottom: `1px solid ${neutral[200]}`,\n        ...baseFont,\n        ...style,\n      }}\n    >\n      <div>\n        <div\n          style={{\n            fontSize: fontSize.lg,\n            fontWeight: 600,\n            color: neutral[900],\n            lineHeight: 1.3,\n          }}\n        >\n          {title}\n        </div>\n        {subtitle && (\n          <div style={{ fontSize: fontSize.xs, color: neutral[400], marginTop: 1 }}>\n            {subtitle}\n          </div>\n        )}\n      </div>\n\n      {/* 用户信息占位 */}\n      <div\n        data-testid=\"topbar-user\"\n        style={{ display: \"flex\", alignItems: \"center\", gap: space.sm }}\n      >\n        <div style={{ textAlign: \"right\" }}>\n          <div style={{ fontSize: fontSize.md, color: neutral[700], fontWeight: 500 }}>\n            {userName}\n          </div>\n          <div style={{ fontSize: fontSize.xs, color: neutral[400] }}>{userRole}</div>\n        </div>\n        <span\n          style={{\n            width: 34,\n            height: 34,\n            borderRadius: \"50%\",\n            backgroundColor: neutral[900],\n            color: \"#FFFFFF\",\n            display: \"inline-flex\",\n            alignItems: \"center\",\n            justifyContent: \"center\",\n            fontSize: fontSize.md,\n            fontWeight: 600,\n          }}\n        >\n          {initials}\n        </span>\n      </div>\n    </header>\n  );\n}\n\n/* ================================ EmptyState ================================\n * 空状态占位：图标 + 标题 + 描述\n */\nexport interface EmptyStateProps {\n  title?: string;\n  description?: string;\n  icon?: ReactNode;\n  action?: ReactNode;\n  style?: CSSProperties;\n  className?: string;\n}\n\nexport function EmptyState({\n  title = \"暂无数据\",\n  description = \"当前还没有内容，稍后再来看看。\",\n  icon,\n  action,\n  style,\n  className,\n}: EmptyStateProps) {\n  return (\n    <div\n      data-testid=\"empty-state\"\n      className={className}\n      style={{\n        display: \"flex\",\n        flexDirection: \"column\",\n        alignItems: \"center\",\n        justifyContent: \"center\",\n        gap: space.md,\n        padding: `${space.xxl}px`,\n        textAlign: \"center\",\n        ...baseFont,\n        ...style,\n      }}\n    >\n      <div\n        aria-hidden\n        style={{\n          width: 64,\n          height: 64,\n          borderRadius: radius.lg,\n          backgroundColor: neutral[100],\n          border: `1px dashed ${neutral[300]}`,\n          display: \"flex\",\n          alignItems: \"center\",\n          justifyContent: \"center\",\n          fontSize: 26,\n          color: neutral[400],\n        }}\n      >\n        {icon ?? \"◌\"}\n      </div>\n      <div>\n        <div style={{ fontSize: fontSize.lg, fontWeight: 600, color: neutral[700] }}>\n          {title}\n        </div>\n        <div style={{ fontSize: fontSize.md, color: neutral[400], marginTop: space.xs }}>\n          {description}\n        </div>\n      </div>\n      {action}\n    </div>\n  );\n}\n",
  "nav.tsx": "/**\n * Agent Platform 共享导航组件库\n * =============================================\n * 从演示原型 nav-hybrid（Dock 悬浮导航 + Cmd+K 命令面板 + 浅色顶栏）提取为\n * 可复用的共享组件，供业务页面（project-list / task-create / task-board /\n * group-chat / dm-chat / task-detail / agent-config / worker-list /\n * worker-install / skills-tools-manage / tool-register / user-management /\n * role-permission 等）统一复用，替换深色 Sidebar。\n *\n * 三个组件独立、可组合（页面可自由选择组合方式）：\n * - NavDock    左侧 Dock 悬浮导航条：毛玻璃胶囊，hover 展开 56→248px，纯 CSS 无 JS\n * - NavTopBar  浅色顶栏：左面包屑 + 居中 Cmd+K 触发框 + 右用户头像\n * - CmdKPanel  Cmd+K 命令面板浮层：居中毛玻璃 + 遮罩；受控开关（open 默认 false，\n *   页面用 useState 管理，onClose 关闭：✕ 按钮 / 遮罩点击 / Esc 键）\n *\n * 铁律（T15）：所有浮层 position: absolute 相对宿主容器（宿主需 position: relative），\n * 严禁 fixed / 100vh / 100vw。颜色 / 间距 / 圆角 / 字号 / 阴影一律取自 ./styles token，\n * 组件内不散落 magic number（导航高亮蓝 #3B82F6 与 styles.roles.product 一致，收敛为具名常量）。\n *\n * 引入方式（页面内相对 import）：\n *   import { NavDock, NavTopBar, CmdKPanel } from \"../_shared/nav\";\n */\nimport { useEffect } from \"react\";\nimport type { CSSProperties, ReactNode } from \"react\";\nimport { neutral, space, radius, fontSize, fontFamily, shadow } from \"./styles\";\n\nconst baseFont: CSSProperties = { fontFamily: fontFamily.body };\n\n/* ------------------------------ 导航语义常量 ------------------------------ */\n/** 导航高亮蓝（与 styles.roles.product.color 一致） */\nconst NAV_ACTIVE = \"#3B82F6\";\n/** 高亮深一档（用于文字 / 选中态底色） */\nconst NAV_ACTIVE_DEEP = \"#2563EB\";\n\n/** Dock 收起 / 展开宽度（56→248px） */\nconst RAIL_W = 56;\nconst RAIL_OPEN_W = 248;\nconst PANEL_W = RAIL_OPEN_W - RAIL_W;\n\n/** Dock 导航项（图标与 Cmd+K 命令面板「导航」组一一对应） */\nexport interface NavItem {\n  key: string;\n  label: string;\n  icon: string;\n}\n\nexport const NAV_ITEMS: NavItem[] = [\n  { key: \"project\", label: \"项目\", icon: \"▤\" },\n  { key: \"board\", label: \"任务看板\", icon: \"☰\" },\n  { key: \"agents\", label: \"Agent 管理\", icon: \"◉\" },\n  { key: \"workers\", label: \"Worker 节点\", icon: \"⚙\" },\n  { key: \"skills\", label: \"技能与工具\", icon: \"◫\" },\n  { key: \"messages\", label: \"消息中心\", icon: \"✉\" },\n  { key: \"users\", label: \"用户管理\", icon: \"☷\" },\n];\n\n/* ------------------------------ scoped 动画与样式 ------------------------------ */\n/** 共享 keyframes：navshared 前缀避免污染其他原型 */\nconst navAnimStyle = `\n  @keyframes navshared-blink { 0%,100%{opacity:1} 50%{opacity:0} }\n  @keyframes navshared-pop { from{opacity:0; transform:translateY(8px) scale(.985)} to{opacity:1; transform:none} }\n  @keyframes navshared-fade { from{opacity:0} to{opacity:1} }\n`;\n\n/* ================================ NavDock ================================\n * 左侧 Dock 悬浮导航条：毛玻璃胶囊、hover 展开 56→248px、activeKey 高亮 +\n * Activity Bar 指示条（::before）。纯 CSS 交互，无 JS 状态。\n * 宿主容器需 position: relative（本组件内部为 absolute 定位）。\n */\nexport interface NavDockProps {\n  /** 当前激活导航 key（对应 NAV_ITEMS.key），命中项高亮 */\n  activeKey?: string;\n  /** 展开面板中的项目名 */\n  projectName?: string;\n  /** 点击导航项回调（key 为导航项 key） */\n  onNavClick?: (key: string) => void;\n  /** 面板内底部扩展插槽（如成员列表 / 在线状态） */\n  children?: ReactNode;\n  style?: CSSProperties;\n  className?: string;\n}\n\nconst dockCss = navAnimStyle + `\n.navdock-dock {\n  position: absolute;\n  left: 12px;\n  top: 50%;\n  transform: translateY(-50%);\n  width: ${RAIL_W}px;\n  display: flex;\n  align-items: stretch;\n  border-radius: ${radius.pill}px;\n  background: rgba(255,255,255,.72);\n  border: 1px solid rgba(15,23,42,.08);\n  backdrop-filter: blur(14px) saturate(1.4);\n  -webkit-backdrop-filter: blur(14px) saturate(1.4);\n  box-shadow: ${shadow.md};\n  z-index: 50;\n  overflow: hidden;\n  transition: width .28s cubic-bezier(.22,1,.36,1), box-shadow .28s ease;\n}\n.navdock-dock:hover {\n  width: ${RAIL_OPEN_W}px;\n  box-shadow: ${shadow.lg};\n}\n.navdock-icons {\n  width: ${RAIL_W}px;\n  flex-shrink: 0;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: ${space.sm}px;\n  padding: ${space.lg}px 0;\n  position: relative;\n  z-index: 2;\n}\n.navdock-icon {\n  position: relative;\n  width: 40px;\n  height: 40px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  border: none;\n  border-radius: ${radius.md}px;\n  background: transparent;\n  color: ${neutral[500]};\n  font-size: ${fontSize.xl}px;\n  line-height: 1;\n  cursor: pointer;\n  font-family: ${fontFamily.body};\n  transition: background-color .15s ease, color .15s ease, transform .15s ease;\n}\n.navdock-icon:hover { background: rgba(59,130,246,.1); color: ${NAV_ACTIVE_DEEP}; transform: translateY(-1px); }\n.navdock-icon[data-active=\"true\"] { background: rgba(59,130,246,.12); color: ${NAV_ACTIVE}; }\n/* Activity Bar 指示条 */\n.navdock-icon[data-active=\"true\"]::before {\n  content: \"\";\n  position: absolute;\n  left: -8px;\n  top: 50%;\n  transform: translateY(-50%);\n  width: 3px;\n  height: 18px;\n  border-radius: ${radius.pill}px;\n  background: ${NAV_ACTIVE};\n}\n.navdock-panel {\n  width: 0;\n  opacity: 0;\n  overflow: hidden;\n  display: flex;\n  flex-direction: column;\n  flex-shrink: 0;\n  transition: width .28s cubic-bezier(.22,1,.36,1), opacity .18s ease .06s;\n  border-left: 1px solid rgba(15,23,42,.06);\n}\n.navdock-dock:hover .navdock-panel {\n  width: ${PANEL_W}px;\n  opacity: 1;\n}\n.navdock-panel-inner {\n  width: ${PANEL_W}px;\n  padding: ${space.lg}px ${space.md}px ${space.md}px;\n  display: flex;\n  flex-direction: column;\n  gap: ${space.md}px;\n  white-space: nowrap;\n}\n.navdock-product { display: flex; align-items: center; gap: ${space.sm}px; }\n.navdock-product-mark {\n  width: 32px; height: 32px; flex-shrink: 0;\n  border-radius: ${radius.md}px;\n  background: linear-gradient(135deg, ${NAV_ACTIVE}, #8B5CF6);\n  color: #FFFFFF;\n  display: inline-flex; align-items: center; justify-content: center;\n  font-weight: 700; font-size: ${fontSize.md}px;\n  box-shadow: ${shadow.sm};\n}\n.navdock-product-name { font-size: ${fontSize.md}px; font-weight: 600; color: ${neutral[900]}; line-height: 1.3; }\n.navdock-product-sub { font-size: ${fontSize.xs}px; color: ${neutral[400]}; margin-top: 1px; }\n.navdock-section-label { font-size: ${fontSize.xs}px; font-weight: 600; color: ${neutral[400]}; letter-spacing: .04em; }\n.navdock-nav { display: flex; flex-direction: column; gap: 2px; }\n.navdock-nav-item {\n  display: flex; align-items: center; gap: ${space.sm + 2}px;\n  padding: ${space.sm}px ${space.sm + 2}px;\n  border: none; border-radius: ${radius.md}px; background: transparent;\n  color: ${neutral[600]}; font-size: ${fontSize.md}px; text-align: left;\n  cursor: pointer; font-family: ${fontFamily.body};\n  transition: background-color .15s ease, color .15s ease;\n}\n.navdock-nav-item:hover { background: rgba(15,23,42,.05); color: ${neutral[900]}; }\n.navdock-nav-item[data-active=\"true\"] { background: rgba(59,130,246,.1); color: ${NAV_ACTIVE_DEEP}; font-weight: 600; }\n.navdock-nav-item-icon { font-size: ${fontSize.md}px; line-height: 1; width: 18px; text-align: center; opacity: .9; }\n.navdock-nav-item[data-active=\"true\"] .navdock-nav-item-icon { opacity: 1; }\n.navdock-extra {\n  margin-top: auto;\n  display: flex;\n  flex-direction: column;\n  gap: ${space.xs + 2}px;\n}\n`;\n\nexport function NavDock({\n  activeKey,\n  projectName = \"Agent 协作平台\",\n  onNavClick,\n  children,\n  style,\n  className,\n}: NavDockProps) {\n  return (\n    <>\n      <style>{dockCss}</style>\n      <div data-testid=\"rail-bar\" className={`navdock-dock${className ? ` ${className}` : \"\"}`} style={style}>\n        {/* 收起态：图标列（hover 高亮 + Activity Bar 指示条） */}\n        <div className=\"navdock-icons\">\n          {NAV_ITEMS.map((item) => (\n            <button\n              key={item.key}\n              type=\"button\"\n              data-testid=\"rail-icon\"\n              data-nav={item.key}\n              data-active={item.key === activeKey ? \"true\" : \"false\"}\n              aria-label={item.label}\n              title={item.label}\n              className=\"navdock-icon\"\n              onClick={onNavClick ? () => onNavClick(item.key) : undefined}\n            >\n              <span aria-hidden>{item.icon}</span>\n            </button>\n          ))}\n        </div>\n\n        {/* 展开态：浮层面板（项目名 + 导航列表 + children 扩展槽） */}\n        <div data-testid=\"rail-panel\" className=\"navdock-panel\">\n          <div className=\"navdock-panel-inner\" style={baseFont}>\n            <div className=\"navdock-product\">\n              <span className=\"navdock-product-mark\" aria-hidden>\n                A\n              </span>\n              <span>\n                <span className=\"navdock-product-name\" style={{ display: \"block\" }}>\n                  {projectName}\n                </span>\n                <span className=\"navdock-product-sub\" style={{ display: \"block\" }}>\n                  智能体协作工作区\n                </span>\n              </span>\n            </div>\n\n            <div>\n              <div className=\"navdock-section-label\" style={{ marginBottom: space.sm }}>\n                导航\n              </div>\n              <div className=\"navdock-nav\">\n                {NAV_ITEMS.map((item) => (\n                  <button\n                    key={item.key}\n                    type=\"button\"\n                    data-testid=\"nav-item\"\n                    data-nav={item.key}\n                    data-active={item.key === activeKey ? \"true\" : \"false\"}\n                    className=\"navdock-nav-item\"\n                    onClick={onNavClick ? () => onNavClick(item.key) : undefined}\n                  >\n                    <span className=\"navdock-nav-item-icon\" aria-hidden>\n                      {item.icon}\n                    </span>\n                    {item.label}\n                  </button>\n                ))}\n              </div>\n            </div>\n\n            {children && <div className=\"navdock-extra\">{children}</div>}\n          </div>\n        </div>\n      </div>\n    </>\n  );\n}\n\n/* ================================ NavTopBar ================================\n * 浅色顶栏：左面包屑（breadcrumb 数组用 › 连接；缺省回退 title/subtitle）+\n * 居中 Cmd+K 触发框（「搜索或输入命令…」+ ⌘K 徽标）+ 右用户头像。\n * 处于文档流（非浮层），height 60 固定。\n */\nexport interface NavTopBarProps {\n  /** 面包屑路径（按序用 › 连接）；提供时替代 title/subtitle 展示 */\n  breadcrumb?: string[];\n  /** 无 breadcrumb 时的左侧标题 */\n  title?: string;\n  /** 无 breadcrumb 时的左侧副标题 */\n  subtitle?: string;\n  userName?: string;\n  userRole?: string;\n  /** 点击 Cmd+K 触发框回调（打开命令面板） */\n  onCmdKClick?: () => void;\n  /** 右侧用户头像后扩展插槽 */\n  children?: ReactNode;\n  style?: CSSProperties;\n  className?: string;\n}\n\nexport function NavTopBar({\n  breadcrumb,\n  title = \"任务看板\",\n  subtitle,\n  userName = \"运营者\",\n  userRole = \"项目管理员\",\n  onCmdKClick,\n  children,\n  style,\n  className,\n}: NavTopBarProps) {\n  const hasBreadcrumb = !!breadcrumb && breadcrumb.length > 0;\n  const initials = userName.slice(0, 1);\n  return (\n    <header\n      data-testid=\"topbar\"\n      className={className}\n      style={{\n        height: 60,\n        flexShrink: 0,\n        display: \"flex\",\n        alignItems: \"center\",\n        justifyContent: \"space-between\",\n        gap: space.xl,\n        padding: `0 ${space.xl}px`,\n        backgroundColor: \"#FFFFFF\",\n        borderBottom: `1px solid ${neutral[200]}`,\n        ...baseFont,\n        ...style,\n      }}\n    >\n      {/* 左侧：面包屑 或 标题 */}\n      {hasBreadcrumb ? (\n        <nav\n          data-testid=\"top-breadcrumb\"\n          aria-label=\"面包屑\"\n          style={{ display: \"flex\", alignItems: \"center\", gap: space.sm, minWidth: 0 }}\n        >\n          {breadcrumb.map((crumb, i) => {\n            const isLast = i === breadcrumb.length - 1;\n            return (\n              <span\n                key={i}\n                style={{ display: \"inline-flex\", alignItems: \"center\", gap: space.sm, minWidth: 0 }}\n              >\n                {i > 0 && (\n                  <span aria-hidden style={{ color: neutral[300], fontSize: fontSize.lg, lineHeight: 1 }}>\n                    ›\n                  </span>\n                )}\n                <span\n                  style={{\n                    fontSize: fontSize.md,\n                    fontWeight: isLast ? 600 : 500,\n                    color: isLast ? neutral[900] : neutral[500],\n                    whiteSpace: \"nowrap\",\n                    overflow: \"hidden\",\n                    textOverflow: \"ellipsis\",\n                  }}\n                >\n                  {crumb}\n                </span>\n              </span>\n            );\n          })}\n        </nav>\n      ) : (\n        <div data-testid=\"top-title\" style={{ minWidth: 0 }}>\n          <div\n            style={{\n              fontSize: fontSize.lg,\n              fontWeight: 600,\n              color: neutral[900],\n              lineHeight: 1.3,\n              whiteSpace: \"nowrap\",\n              overflow: \"hidden\",\n              textOverflow: \"ellipsis\",\n            }}\n          >\n            {title}\n          </div>\n          {subtitle && (\n            <div style={{ fontSize: fontSize.xs, color: neutral[400], marginTop: 1 }}>{subtitle}</div>\n          )}\n        </div>\n      )}\n\n      {/* 中部：Cmd+K 触发框 */}\n      <button\n        type=\"button\"\n        data-testid=\"cmdk-trigger\"\n        aria-label=\"打开命令面板（⌘K）\"\n        onClick={onCmdKClick}\n        style={{\n          display: \"flex\",\n          alignItems: \"center\",\n          gap: space.sm,\n          width: 280,\n          padding: `${space.sm}px ${space.md}px`,\n          borderRadius: radius.md,\n          backgroundColor: neutral[50],\n          border: `1px solid ${neutral[200]}`,\n          cursor: \"pointer\",\n          fontFamily: fontFamily.body,\n          boxShadow: shadow.sm,\n        }}\n      >\n        <span aria-hidden style={{ fontSize: fontSize.lg, color: neutral[400], lineHeight: 1 }}>\n          ⌕\n        </span>\n        <span\n          style={{\n            flex: 1,\n            textAlign: \"left\",\n            fontSize: fontSize.md,\n            color: neutral[400],\n            whiteSpace: \"nowrap\",\n            overflow: \"hidden\",\n            textOverflow: \"ellipsis\",\n          }}\n        >\n          搜索或输入命令…\n        </span>\n        <span\n          aria-hidden\n          style={{\n            fontSize: fontSize.xs,\n            fontWeight: 600,\n            color: neutral[500],\n            backgroundColor: \"#FFFFFF\",\n            border: `1px solid ${neutral[200]}`,\n            padding: \"1px 6px\",\n            borderRadius: radius.sm,\n          }}\n        >\n          ⌘K\n        </span>\n      </button>\n\n      {/* 右侧：用户信息 + 头像 + children 插槽 */}\n      <div style={{ display: \"flex\", alignItems: \"center\", gap: space.sm }}>\n        <div style={{ textAlign: \"right\" }}>\n          <div style={{ fontSize: fontSize.md, color: neutral[700], fontWeight: 500 }}>{userName}</div>\n          <div style={{ fontSize: fontSize.xs, color: neutral[400] }}>{userRole}</div>\n        </div>\n        <span\n          style={{\n            width: 34,\n            height: 34,\n            borderRadius: \"50%\",\n            backgroundColor: neutral[900],\n            color: \"#FFFFFF\",\n            display: \"inline-flex\",\n            alignItems: \"center\",\n            justifyContent: \"center\",\n            fontSize: fontSize.md,\n            fontWeight: 600,\n            userSelect: \"none\",\n          }}\n        >\n          {initials}\n        </span>\n        {children}\n      </div>\n    </header>\n  );\n}\n\n/* ================================ CmdKPanel ================================\n * Cmd+K 命令面板浮层：居中毛玻璃 + 遮罩（absolute inset:0），受控开关。\n * 页面以 useState 管理 open，点击 NavTopBar 的 cmdk-trigger（onCmdKClick）打开，\n * 通过 onClose 关闭（右上 ✕ / 遮罩点击 / Esc 键）。\n * items 按 group 分组渲染；icon 与 Dock 图标对应（导航组 ▤ ☰ ◉）。\n * 宿主容器需 position: relative。\n */\nexport interface CmdKItem {\n  group: string;\n  label: string;\n  icon: string;\n  /** 是否高亮（模拟键盘选中态） */\n  active?: boolean;\n}\n\nexport interface CmdKPanelProps {\n  /** 是否展示（默认 false，受控开关；由父级 useState 管理） */\n  open?: boolean;\n  /** 关闭回调（✕ 按钮 / 遮罩点击 / Esc 键触发） */\n  onClose?: () => void;\n  /** 命令项（默认提供「导航 / 操作」两组，导航 7 条与 Dock 图标对应） */\n  items?: CmdKItem[];\n  /** 点击命令项回调 */\n  onSelect?: (label: string) => void;\n  /** 底部提示区扩展插槽 */\n  children?: ReactNode;\n  style?: CSSProperties;\n  className?: string;\n}\n\nconst DEFAULT_CMDK_ITEMS: CmdKItem[] = [\n  { group: \"导航\", label: \"切换项目\", icon: \"▤\" },\n  { group: \"导航\", label: \"任务看板\", icon: \"☰\" },\n  { group: \"导航\", label: \"Agent 管理\", icon: \"◉\" },\n  { group: \"导航\", label: \"Worker 节点\", icon: \"⚙\" },\n  { group: \"导航\", label: \"技能与工具\", icon: \"◫\" },\n  { group: \"导航\", label: \"消息中心\", icon: \"✉\" },\n  { group: \"导航\", label: \"用户管理\", icon: \"☷\" },\n  { group: \"操作\", label: \"新建任务\", icon: \"＋\" },\n  { group: \"操作\", label: \"查看产出物\", icon: \"▦\" },\n  { group: \"操作\", label: \"查看 Agent 会话\", icon: \"◷\" },\n];\n\nconst panelCss = navAnimStyle + `\n.navcmdk-overlay {\n  position: absolute;\n  inset: 0;\n  z-index: 40;\n  display: flex;\n  align-items: flex-start;\n  justify-content: center;\n  padding-top: 12%;\n}\n.navcmdk-mask {\n  position: absolute;\n  inset: 0;\n  background-color: rgba(15,23,42,.32);\n  animation: navshared-fade .18s ease-out;\n}\n.navcmdk-panel {\n  position: relative;\n  width: 600px;\n  max-width: calc(100% - 48px);\n  max-height: min(560px, 74%);\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  border-radius: ${radius.lg}px;\n  background-color: rgba(255,255,255,.84);\n  backdrop-filter: blur(20px) saturate(1.5);\n  -webkit-backdrop-filter: blur(20px) saturate(1.5);\n  border: 1px solid rgba(255,255,255,.72);\n  box-shadow: ${shadow.lg};\n  animation: navshared-pop .16s ease-out;\n}\n.navcmdk-item {\n  width: 100%;\n  display: flex;\n  align-items: center;\n  gap: ${space.md}px;\n  padding: ${space.sm + 2}px ${space.md}px;\n  border-radius: ${radius.md}px;\n  border: none;\n  cursor: pointer;\n  text-align: left;\n  background: transparent;\n  color: ${neutral[700]};\n  font-family: ${fontFamily.body};\n  transition: background-color .15s ease, color .15s ease;\n}\n.navcmdk-item:hover { background: rgba(15,23,42,.05); color: ${neutral[900]}; }\n.navcmdk-item[data-active=\"true\"] { background: ${NAV_ACTIVE_DEEP}; color: #FFFFFF; }\n.navcmdk-item-icon {\n  width: 30px;\n  height: 30px;\n  flex-shrink: 0;\n  border-radius: ${radius.sm}px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  font-size: ${fontSize.lg}px;\n  line-height: 1;\n  background-color: ${neutral[100]};\n  color: ${NAV_ACTIVE};\n}\n.navcmdk-item[data-active=\"true\"] .navcmdk-item-icon { background: rgba(255,255,255,.18); color: #FFFFFF; }\n.navcmdk-item-label {\n  flex: 1;\n  min-width: 0;\n  font-size: ${fontSize.md}px;\n  font-weight: 600;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.navcmdk-close {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 26px;\n  height: 26px;\n  flex-shrink: 0;\n  margin-left: ${space.xs}px;\n  border-radius: 50%;\n  border: none;\n  cursor: pointer;\n  background: transparent;\n  color: ${neutral[400]};\n  font-size: ${fontSize.lg}px;\n  line-height: 1;\n  transition: background-color .15s ease, color .15s ease;\n}\n.navcmdk-close:hover { background-color: ${neutral[100]}; color: ${neutral[900]}; }\n`;\n\nexport function CmdKPanel({\n  open = false,\n  items = DEFAULT_CMDK_ITEMS,\n  onSelect,\n  onClose,\n  children,\n  style,\n  className,\n}: CmdKPanelProps) {\n  // Esc 键关闭：open 时才挂监听，卸载/关闭时清理\n  useEffect(() => {\n    if (!open || !onClose) return;\n    const handleKey = (e: KeyboardEvent) => {\n      if (e.key === \"Escape\") onClose();\n    };\n    window.addEventListener(\"keydown\", handleKey);\n    return () => window.removeEventListener(\"keydown\", handleKey);\n  }, [open, onClose]);\n\n  if (!open) return null;\n\n  // 按 group 保序分组\n  const groups: { group: string; items: CmdKItem[] }[] = [];\n  for (const item of items) {\n    const g = groups.find((x) => x.group === item.group);\n    if (g) g.items.push(item);\n    else groups.push({ group: item.group, items: [item] });\n  }\n\n  return (\n    <div\n      data-testid=\"cmdk-panel\"\n      className={`navcmdk-overlay${className ? ` ${className}` : \"\"}`}\n      style={baseFont}\n    >\n      <style>{panelCss}</style>\n      {/* 轻遮罩：主体内容仍然可辨，点击关闭 */}\n      <div aria-hidden className=\"navcmdk-mask\" onClick={onClose} />\n\n      {/* 面板：毛玻璃 + 圆角 + 阴影 */}\n      <div className=\"navcmdk-panel\" style={style}>\n        {/* 搜索输入（光标闪烁模拟聚焦态） */}\n        <div\n          data-testid=\"cmdk-search\"\n          style={{\n            display: \"flex\",\n            alignItems: \"center\",\n            gap: space.sm,\n            padding: `${space.lg}px ${space.xl}px`,\n            borderBottom: `1px solid ${neutral[200]}`,\n            backgroundColor: \"rgba(255,255,255,.55)\",\n          }}\n        >\n          <span aria-hidden style={{ fontSize: 18, color: neutral[400], lineHeight: 1 }}>\n            ⌕\n          </span>\n          <input\n            autoFocus\n            readOnly\n            placeholder=\"搜索或输入命令…\"\n            aria-label=\"搜索命令\"\n            style={{\n              flex: 1,\n              minWidth: 0,\n              border: \"none\",\n              outline: \"none\",\n              background: \"transparent\",\n              fontSize: fontSize.xl,\n              fontWeight: 500,\n              color: neutral[900],\n              fontFamily: fontFamily.body,\n              padding: 0,\n            }}\n          />\n          <span\n            aria-hidden\n            style={{\n              width: 2,\n              height: 18,\n              flexShrink: 0,\n              borderRadius: 1,\n              backgroundColor: NAV_ACTIVE_DEEP,\n              animation: \"navshared-blink 1.05s step-end infinite\",\n            }}\n          />\n          <span\n            style={{\n              fontSize: fontSize.xs,\n              color: neutral[400],\n              border: `1px solid ${neutral[200]}`,\n              borderRadius: radius.sm,\n              padding: \"1px 6px\",\n              flexShrink: 0,\n            }}\n          >\n            ESC\n          </span>\n          {/* 关闭按钮：右上角 ✕（圆形 hover） */}\n          <button\n            type=\"button\"\n            data-testid=\"cmdk-close\"\n            aria-label=\"关闭命令面板\"\n            className=\"navcmdk-close\"\n            onClick={onClose}\n          >\n            ✕\n          </button>\n        </div>\n\n        {/* 命令分组列表 */}\n        <div style={{ flex: 1, overflow: \"auto\", padding: space.sm }}>\n          {groups.map((g) => (\n            <div key={g.group}>\n              <div\n                style={{\n                  padding: `${space.sm}px ${space.md}px ${space.xs}px`,\n                  fontSize: fontSize.xs,\n                  fontWeight: 600,\n                  color: neutral[400],\n                  textTransform: \"uppercase\",\n                  letterSpacing: 0.06,\n                }}\n              >\n                {g.group}\n              </div>\n              {g.items.map((item) => (\n                <button\n                  key={item.label}\n                  type=\"button\"\n                  data-testid=\"cmdk-item\"\n                  data-active={item.active ? \"true\" : \"false\"}\n                  className=\"navcmdk-item\"\n                  onClick={onSelect ? () => onSelect(item.label) : undefined}\n                >\n                  <span className=\"navcmdk-item-icon\" aria-hidden>\n                    {item.icon}\n                  </span>\n                  <span className=\"navcmdk-item-label\">{item.label}</span>\n                </button>\n              ))}\n            </div>\n          ))}\n        </div>\n\n        {/* 底部提示（children 可覆盖） */}\n        <div\n          style={{\n            display: \"flex\",\n            alignItems: \"center\",\n            gap: space.lg,\n            padding: `${space.sm}px ${space.lg}px`,\n            borderTop: `1px solid ${neutral[200]}`,\n            backgroundColor: \"rgba(255,255,255,.55)\",\n            fontSize: fontSize.xs,\n            color: neutral[400],\n          }}\n        >\n          {children ?? (\n            <>\n              <span>↑↓ 选择</span>\n              <span>↵ 打开</span>\n              <span>⌘K 唤起</span>\n              <span style={{ marginLeft: \"auto\" }}>Dock 常驻 · ⌘K 全览</span>\n            </>\n          )}\n        </div>\n      </div>\n    </div>\n  );\n}\n",
  "ui.tsx": "import type { ButtonHTMLAttributes, ReactNode } from \"react\";\n\n/**\n * 原型页面共享 UI 小组件\n * =====================================================\n * 供 src/prototypes/<name>/ 下的原型页面复用：\n *  - StatusBadge：语义色状态徽标（success/warning/danger/info/neutral/brand）\n *  - ProgressBar：进度条\n *  - Avatar：取姓名首字符的圆形头像\n *  - Button：主 / 次 / 危险按钮\n *  - 常用内联图标\n * 全部基于 index.css 中的设计 token（Tailwind 工具类），无第三方依赖。\n */\n\nexport type Tone = \"success\" | \"warning\" | \"danger\" | \"info\" | \"neutral\" | \"brand\";\n\nconst toneClass: Record<Tone, string> = {\n  success: \"bg-success-50 text-success-700 ring-success-600/20\",\n  warning: \"bg-warning-50 text-warning-700 ring-warning-500/25\",\n  danger: \"bg-danger-50 text-danger-700 ring-danger-500/20\",\n  info: \"bg-info-50 text-info-700 ring-info-500/20\",\n  neutral: \"bg-slate-100 text-slate-600 ring-slate-500/15\",\n  brand: \"bg-brand-50 text-brand-700 ring-brand-500/25\",\n};\n\nconst dotClass: Record<Tone, string> = {\n  success: \"bg-success-500\",\n  warning: \"bg-warning-500\",\n  danger: \"bg-danger-500\",\n  info: \"bg-info-500\",\n  neutral: \"bg-slate-400\",\n  brand: \"bg-brand-500\",\n};\n\nexport function StatusBadge({\n  tone = \"neutral\",\n  dot = true,\n  children,\n}: {\n  tone?: Tone;\n  dot?: boolean;\n  children: ReactNode;\n}) {\n  return (\n    <span\n      className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-0.5 text-xs font-medium ring-1 ring-inset ${toneClass[tone]}`}\n    >\n      {dot && <span className={`size-1.5 rounded-full ${dotClass[tone]}`} />}\n      {children}\n    </span>\n  );\n}\n\nexport function ProgressBar({\n  value,\n  tone = \"brand\",\n}: {\n  value: number;\n  tone?: \"brand\" | \"success\" | \"warning\" | \"danger\";\n}) {\n  const barClass = {\n    brand: \"bg-brand-500\",\n    success: \"bg-success-500\",\n    warning: \"bg-warning-500\",\n    danger: \"bg-danger-500\",\n  }[tone];\n  return (\n    <div className=\"h-1.5 w-full overflow-hidden rounded-full bg-slate-100\">\n      <div\n        className={`h-full rounded-full ${barClass} transition-all`}\n        style={{ width: `${Math.min(100, Math.max(0, value))}%` }}\n      />\n    </div>\n  );\n}\n\nconst avatarPalette = [\n  \"bg-brand-100 text-brand-700\",\n  \"bg-info-100 text-info-700\",\n  \"bg-success-100 text-success-700\",\n  \"bg-warning-100 text-warning-700\",\n  \"bg-danger-100 text-danger-700\",\n  \"bg-slate-200 text-slate-700\",\n];\n\nexport function Avatar({ name, size = \"md\" }: { name: string; size?: \"sm\" | \"md\" }) {\n  const idx = [...name].reduce((acc, ch) => acc + (ch.codePointAt(0) ?? 0), 0) % avatarPalette.length;\n  const sizeClass = size === \"sm\" ? \"size-6 text-xs\" : \"size-8 text-sm\";\n  return (\n    <span\n      className={`inline-flex shrink-0 items-center justify-center rounded-full font-medium ${sizeClass} ${avatarPalette[idx]}`}\n    >\n      {[...name][0] ?? \"?\"}\n    </span>\n  );\n}\n\nexport function Button({\n  variant = \"primary\",\n  className = \"\",\n  children,\n  ...rest\n}: {\n  variant?: \"primary\" | \"outline\" | \"danger\" | \"ghost\";\n  className?: string;\n  children: ReactNode;\n} & ButtonHTMLAttributes<HTMLButtonElement>) {\n  const base =\n    \"inline-flex items-center justify-center gap-1.5 rounded-[--radius-control] px-3.5 py-1.5 text-sm font-medium transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-brand-500 disabled:opacity-50\";\n  const variantClass = {\n    primary: \"bg-brand-600 text-white hover:bg-brand-700\",\n    outline: \"border border-slate-200 bg-white text-slate-700 hover:bg-slate-50\",\n    danger: \"bg-danger-500 text-white hover:bg-danger-600\",\n    ghost: \"text-slate-600 hover:bg-slate-100 hover:text-slate-900\",\n  }[variant];\n  return (\n    <button className={`${base} ${variantClass} ${className}`} {...rest}>\n      {children}\n    </button>\n  );\n}\n\n/* ---------- 内联图标（stroke 风格，currentColor） ---------- */\n\nfunction Icon({ className = \"size-4\", children }: { className?: string; children: ReactNode }) {\n  return (\n    <svg\n      viewBox=\"0 0 24 24\"\n      fill=\"none\"\n      stroke=\"currentColor\"\n      strokeWidth=\"2\"\n      strokeLinecap=\"round\"\n      strokeLinejoin=\"round\"\n      className={className}\n      aria-hidden=\"true\"\n    >\n      {children}\n    </svg>\n  );\n}\n\nexport const IconSearch = ({ className }: { className?: string }) => (\n  <Icon className={className}>\n    <circle cx=\"11\" cy=\"11\" r=\"7\" />\n    <path d=\"m21 21-4.3-4.3\" />\n  </Icon>\n);\n\nexport const IconPlus = ({ className }: { className?: string }) => (\n  <Icon className={className}>\n    <path d=\"M12 5v14M5 12h14\" />\n  </Icon>\n);\n\nexport const IconEdit = ({ className }: { className?: string }) => (\n  <Icon className={className}>\n    <path d=\"M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z\" />\n    <path d=\"m15 5 4 4\" />\n  </Icon>\n);\n\nexport const IconMore = ({ className }: { className?: string }) => (\n  <Icon className={className}>\n    <circle cx=\"5\" cy=\"12\" r=\"1\" fill=\"currentColor\" stroke=\"none\" />\n    <circle cx=\"12\" cy=\"12\" r=\"1\" fill=\"currentColor\" stroke=\"none\" />\n    <circle cx=\"19\" cy=\"12\" r=\"1\" fill=\"currentColor\" stroke=\"none\" />\n  </Icon>\n);\n\nexport const IconChevronLeft = ({ className }: { className?: string }) => (\n  <Icon className={className}>\n    <path d=\"m15 18-6-6 6-6\" />\n  </Icon>\n);\n\nexport const IconChevronRight = ({ className }: { className?: string }) => (\n  <Icon className={className}>\n    <path d=\"m9 18 6-6-6-6\" />\n  </Icon>\n);\n\nexport const IconLock = ({ className }: { className?: string }) => (\n  <Icon className={className}>\n    <rect width=\"18\" height=\"11\" x=\"3\" y=\"11\" rx=\"2\" />\n    <path d=\"M7 11V7a5 5 0 0 1 10 0v4\" />\n  </Icon>\n);\n\nexport const IconClock = ({ className }: { className?: string }) => (\n  <Icon className={className}>\n    <circle cx=\"12\" cy=\"12\" r=\"9\" />\n    <path d=\"M12 7v5l3 2\" />\n  </Icon>\n);\n\nexport const IconMonitor = ({ className }: { className?: string }) => (\n  <Icon className={className}>\n    <rect width=\"18\" height=\"13\" x=\"3\" y=\"4\" rx=\"2\" />\n    <path d=\"M8 21h8M12 17v4\" />\n  </Icon>\n);\n\nexport const IconSmartphone = ({ className }: { className?: string }) => (\n  <Icon className={className}>\n    <rect width=\"13\" height=\"20\" x=\"5.5\" y=\"2\" rx=\"3\" />\n    <path d=\"M12 18h.01\" />\n  </Icon>\n);\n\nexport const IconRefresh = ({ className }: { className?: string }) => (\n  <Icon className={className}>\n    <path d=\"M3 12a9 9 0 0 1 15-6.7L21 8\" />\n    <path d=\"M21 3v5h-5\" />\n    <path d=\"M21 12a9 9 0 0 1-15 6.7L3 16\" />\n    <path d=\"M3 21v-5h5\" />\n  </Icon>\n);\n",
  "types.ts": "import type { ComponentType } from \"react\";\n\n/**\n * 原型页面（Prototype）注册契约\n * ============================================================\n * 每个原型页面是一个 React 组件，在 src/prototypes/registry.ts 中注册。\n * 模板（PrototypeViewer）会自动列出所有已注册原型，支持：\n *  - 页面内切换展示不同原型\n *  - PC / 移动端设备模拟展示\n *\n * 新增原型页面的步骤：\n *  1. 在 src/prototypes/<name>/ 下创建原型组件（自由实现，可用任何组件库/CSS）\n *  2. 在 src/prototypes/registry.ts 中导入并注册\n * 完成，无需改动模板代码。\n */\n\n/** 设备类型：桌面 PC / 移动端 */\nexport type DeviceType = \"desktop\" | \"mobile\";\n\n/**\n * 设备尺寸定义（用于 DeviceFrame 切换）\n * 后续可扩展：平板、折叠屏等\n */\nexport interface DeviceSpec {\n  /** 展示宽度 px（内容区宽度） */\n  width: number;\n  /** 展示高度 px（内容区高度，0 表示自适应内容高度） */\n  height: number;\n  /** 设备名称（展示在切换器上） */\n  label: string;\n}\n\n/** 设备规格表：模板内建 PC 与移动端两档 */\nexport const DEVICE_SPECS: Record<DeviceType, DeviceSpec> = {\n  desktop: { width: 1280, height: 800, label: \"PC\" },\n  mobile: { width: 390, height: 844, label: \"移动端\" },\n};\n\n/** 原型元信息 */\nexport interface PrototypeMeta {\n  /** 唯一标识（用于 URL hash 定位，如 #agent-list） */\n  id: string;\n  /** 展示名称（导航/切换器上显示） */\n  name: string;\n  /** 分组（如 \"管理页\" / \"编排\" / \"审批\"，用于导航分组） */\n  group?: string;\n  /** 可选描述 */\n  description?: string;\n}\n\n/** 原型定义：元信息 + 组件 */\nexport interface PrototypeDef {\n  meta: PrototypeMeta;\n  /** 原型页面组件（内部自行撑满高度，适配不同设备宽度） */\n  Component: ComponentType<PrototypeRenderProps>;\n}\n\n/** 传给原型组件的渲染上下文 props */\nexport interface PrototypeRenderProps {\n  /** 当前模拟的设备类型（原型内部可据此调整布局细节） */\n  device: DeviceType;\n  /** 当前模拟的设备宽度 px */\n  deviceWidth: number;\n}\n"
};
